~~~csharp
public sealed class Account
{
    private readonly List<IAccountEvent> _pending = [];
    public Guid Id { get; private set; }
    public decimal Balance { get; private set; }
    public bool Frozen { get; private set; }
    public long Version { get; private set; } = -1;
    public IReadOnlyList<IAccountEvent> PendingEvents => _pending;

    public static Account Load(IEnumerable<IAccountEvent> history)
    {
        var a = new Account();
        foreach (var e in history) { a.Apply(e); a.Version++; }
        return a;
    }

    public void Withdraw(decimal amount, string reference, DateTimeOffset now)
    {
        if (Frozen) throw new DomainException("Account frozen");
        if (amount <= 0) throw new DomainException("Amount must be positive");
        if (amount > Balance) throw new DomainException("Insufficient funds");
        Raise(new FundsWithdrawn(Id, amount, reference, now));   // time passed in, not read inside Apply
    }

    private void Raise(IAccountEvent e) { Apply(e); _pending.Add(e); }

    private void Apply(IAccountEvent e)                          // no rules, no I/O, no clock
    {
        switch (e)
        {
            case AccountOpened o:  Id = o.AccountId; break;
            case FundsDeposited d: Balance += d.Amount; break;
            case FundsWithdrawn w: Balance -= w.Amount; break;
            case AccountFrozen:    Frozen = true; break;
        }
    }
}
