public async Task<Result> Handle(Withdraw cmd, CancellationToken ct)
{
    var stream = $"account-{cmd.AccountId}";
    for (var attempt = 1; attempt <= 3; attempt++)
    {
        var (events, version) = await store.ReadStreamAsync(stream, ct);
        var account = Account.Load(events);
        try { account.Withdraw(cmd.Amount, cmd.Reference, clock.UtcNow); }
        catch (DomainException ex) { return Result.Rejected(ex.Message); }

        try
        {
            await store.AppendAsync(stream, expectedVersion: version, account.PendingEvents,
                new EventMetadata(cmd.CommandId, cmd.CorrelationId, cmd.UserId), ct);
            return Result.Ok(version + account.PendingEvents.Count);
        }
        catch (WrongExpectedVersionException) when (attempt < 3)
        {
            await Task.Delay(Random.Shared.Next(10, 50) * attempt, ct);   // re-decide on fresh state
        }
    }
    return Result.Conflict("Account is being modified concurrently");
}
