public sealed class PeriodCloseHandler(IEventStore store, IClock clock)
{
    public async Task CloseAsync(Guid accountId, YearMonth period, CancellationToken ct)
    {
        var current = StreamIds.Period(accountId, period);       // "account-{id}-2026-09"
        var (events, version) = await store.ReadStreamAsync<ILedgerEvent>(current, ct);
        var state = events.Aggregate(PeriodState.Initial, PeriodDecider.Evolve);
        if (state.Closed) return;                                  // idempotent

        var closed = new PeriodClosed(accountId, period, state.Balance, state.Debits, state.Credits,
                                      PeriodHash.Compute(events), clock.UtcNow);
        await store.AppendAsync(current, version, [closed], ct);

        var next = StreamIds.Period(accountId, period.Next());
        await store.AppendAsync(next, ExpectedVersion.NoStream,
            [new PeriodOpened(accountId, period.Next(), state.Balance, current)], ct);
    }
}
