public sealed class BranchExposureProjector(IEventStore store, IDbContextFactory<ReadDb> dbs, ILogger<BranchExposureProjector> log) : BackgroundService
{
    const string Name = "branch-exposure-v3";

    protected override async Task ExecuteAsync(CancellationToken ct)
    {
