        {
            await using var db = await dbs.CreateDbContextAsync(ct);
            var cp = await db.Checkpoints.FindAsync([Name], ct) ?? db.Checkpoints.Add(new Checkpoint(Name, 0)).Entity;
            var batch = await store.ReadAllAsync(fromPosition: cp.Position + 1, max: 500, categories: ["loan"], ct);
