            await using var tx = await db.Database.BeginTransactionAsync(ct);
            foreach (var e in batch)
            {
                var row = await db.Exposure.FindAsync([e.StreamId], ct);
                if (row is not null && e.StreamVersion <= row.LastVersion) continue;    // idempotent
                row ??= db.Exposure.Add(new ExposureRow { LoanStream = e.StreamId }).Entity;
                ExposureEvolve.Apply(row, e.Data);
                row.LastVersion = e.StreamVersion;
            }
            cp.Position = batch[^1].GlobalPosition;                                   // same transaction
            await db.SaveChangesAsync(ct);
            await tx.CommitAsync(ct);
        }
