    // As known at a point in time: replay what had been recorded by then
    public static PositionState AsKnownAt(IEnumerable<StoredEvent> stream, DateTimeOffset recordedCutoff) =>
        stream.Where(e => e.RecordedAt <= recordedCutoff)
              .Select(e => (IPositionEvent)e.Data)
              .Aggregate(PositionState.Initial, PositionDecider.Evolve);

    // As true at a business date, with everything known now (includes late bookings)
    public static PositionState AsOfEffective(IEnumerable<StoredEvent> stream, DateOnly effective) =>
        stream.Select(e => (IPositionEvent)e.Data)
              .Where(e => e.EffectiveDate <= effective)
              .OrderBy(e => e.EffectiveDate).ThenBy(e => e.Sequence)
              .Aggregate(PositionState.Initial, PositionDecider.Evolve);

    // Both: "on 2 July, what did we believe the 30 June position was?"
    public static PositionState Bitemporal(IEnumerable<StoredEvent> s, DateOnly effective, DateTimeOffset known) =>
        AsOfEffective(s.Where(e => e.RecordedAt <= known), effective);
