public sealed class UpcasterChain(IEnumerable<IUpcaster> all)
{
    private readonly Dictionary<(string, int), IUpcaster> _map = all.ToDictionary(u => (u.EventType, u.FromVersion));

    public (string Type, JsonObject Json) ToCurrent(string type, int version, JsonObject json)
    {
        while (_map.TryGetValue((type, version), out var u)) { (type, json) = u.Upcast(json); version++; }
        return (type, json);
    }
