                                     string CaseId, Guid RequestedBy, Guid ApprovedBy, DateTimeOffset At) : ILedgerEvent;

public static IReadOnlyList<ILedgerEvent> Decide(ReverseDeposit cmd, LedgerState s)
{
    if (cmd.RequestedBy == cmd.ApprovedBy) throw new DomainException("Maker-checker: approver must differ");
    if (!s.Deposits.TryGetValue(cmd.OriginalEventId, out var original)) throw new DomainException("Unknown deposit");
    if (s.Reversed.Contains(cmd.OriginalEventId)) return [];                                   // idempotent
    return [new DepositReversed(s.Id, cmd.OriginalEventId, original.Amount, cmd.Reason, cmd.CaseId,
                                cmd.RequestedBy, cmd.ApprovedBy, cmd.At)];
}

public static LedgerState Evolve(LedgerState s, ILedgerEvent e) => e switch
{
    FundsDeposited d  => s with { Balance = s.Balance + d.Amount, Deposits = s.Deposits.Add(d.EventId, d) },
    DepositReversed r => s with { Balance = s.Balance - r.Amount, Reversed = s.Reversed.Add(r.OriginalEventId) },
    _ => s
