    public async Task<JsonObject> EncryptAsync(Guid subject, JsonObject evt, IEnumerable<string> piiFields, CancellationToken ct)
    {
        var key = await keys.GetOrCreateAsync(subject, ct);                 // AES-256 data key, wrapped by KMS
        foreach (var f in piiFields)
            if (evt[f] is JsonValue v) evt[f] = Aead.Encrypt(key, v.ToString(), associatedData: subject.ToByteArray());
        evt["_pii"] = new JsonObject { ["subject"] = subject.ToString(), ["keyId"] = key.Id };
        return evt;
    }

    public async Task<JsonObject> DecryptAsync(JsonObject evt, IEnumerable<string> piiFields, CancellationToken ct)
    {
        var subject = Guid.Parse(evt["_pii"]!["subject"]!.GetValue<string>());
        var key = await keys.TryGetAsync(subject, ct);
        foreach (var f in piiFields)
            evt[f] = key is null ? "[erased]" : Aead.Decrypt(key, evt[f]!.GetValue<string>(), subject.ToByteArray());
        return evt;
    }

    public Task EraseAsync(Guid subject, CancellationToken ct) => keys.DeleteAsync(subject, ct);  // then publish SubjectErased
