    var state = await RebuildByScanningPartition(topic: "accounts", key: accountId.ToString(), ct);   // slow
    if (amount > state.Balance) throw new DomainException("Insufficient funds");

    // 2. No conditional append: a concurrent producer may have appended meanwhile
    await producer.ProduceAsync("accounts", new Message<string, string>
    {
        Key = accountId.ToString(),
        Value = JsonSerializer.Serialize(new FundsWithdrawn(accountId, amount, "w", DateTimeOffset.UtcNow))
    }, ct);                                                   // both racing withdrawals succeed: overdraft
