// Single writer per hot stream with micro-batching
public sealed class StreamOwner(string stream, IEventStore store) : IAsyncDisposable
{
    private readonly Channel<(IAccountCommand Cmd, TaskCompletionSource<Result> Done)> _inbox = Channel.CreateUnbounded<(IAccountCommand, TaskCompletionSource<Result>)>();
    private AccountState _state = AccountState.Initial; private long _version = -1;

    public Task<Result> Send(IAccountCommand c) { var tcs = new TaskCompletionSource<Result>(); _inbox.Writer.TryWrite((c, tcs)); return tcs.Task; }

    public async Task RunAsync(CancellationToken ct)
    {
        (_state, _version) = await store.LoadAsync(stream, AccountDecider.Initial, AccountDecider.Evolve, ct);
        while (await _inbox.Reader.WaitToReadAsync(ct))
        {
            var batch = new List<(IAccountCommand, TaskCompletionSource<Result>, IReadOnlyList<IAccountEvent>)>();
            var events = new List<IAccountEvent>(); var s = _state;
            while (batch.Count < 500 && _inbox.Reader.TryRead(out var item))
            {
                try { var ev = AccountDecider.Decide(item.Cmd, s); s = ev.Aggregate(s, AccountDecider.Evolve); events.AddRange(ev); batch.Add((item.Cmd, item.Done, ev)); }
                catch (DomainException ex) { item.Done.SetResult(Result.Rejected(ex.Message)); }
            }
            _version = await store.AppendAsync(stream, _version, events, ct);    // no conflicts: sole writer
            _state = s;
            foreach (var (_, done, _) in batch) done.SetResult(Result.Ok(_version));
        }
    }
    public ValueTask DisposeAsync() { _inbox.Writer.TryComplete(); return ValueTask.CompletedTask; }
}
