public sealed class CachedAggregateLoader(IEventStore store, IMemoryCache cache)
{
    public async Task<(AccountState State, long Version)> LoadAsync(string stream, CancellationToken ct)
    {
        var (state, version) = cache.TryGetValue(stream, out (AccountState, long) hit) ? hit : (AccountDecider.Initial, -1L);

        await foreach (var e in store.ReadForwardAsync(stream, fromVersion: version + 1, ct))   // tail read only
        {
            state = AccountDecider.Evolve(state, (IAccountEvent)e.Data);
            version = e.StreamVersion;
        }
        cache.Set(stream, (state, version), new MemoryCacheEntryOptions { SlidingExpiration = TimeSpan.FromMinutes(10), Size = 1 });
        return (state, version);
    }

    public void Evict(string stream) => cache.Remove(stream);     // on WrongExpectedVersion
}
