public sealed record JournalEntryPosted(Guid EntryId, string Journal, IReadOnlyList<JournalLine> Lines,
                                        string Narrative, DateOnly EffectiveDate, Guid? ReversesEntryId, DateTimeOffset At);

public static IReadOnlyList<object> Decide(PostEntry cmd, JournalState s)
{
    if (s.Closed) throw new DomainException($"Journal {s.Journal} is closed");
    if (s.Entries.Contains(cmd.EntryId)) return [];                                         // idempotent
    if (cmd.Lines.Count < 2) throw new DomainException("At least two lines");
    foreach (var g in cmd.Lines.GroupBy(l => l.Currency))
        if (g.Sum(l => l.Debit) != g.Sum(l => l.Credit))
            throw new DomainException($"Entry does not balance in {g.Key}");
    if (cmd.Lines.Any(l => l.Debit < 0 || l.Credit < 0 || (l.Debit > 0 && l.Credit > 0)))
        throw new DomainException("Each line is a positive debit or credit");
    return [new JournalEntryPosted(cmd.EntryId, s.Journal, cmd.Lines, cmd.Narrative, cmd.EffectiveDate, null, cmd.At)];
}
