public static class EventChain
{
    public static byte[] Hash(byte[] previous, StoredEventBytes e)
    {
        using var h = IncrementalHash.CreateHash(HashAlgorithmName.SHA256);
        h.AppendData(previous);
        h.AppendData(Encoding.UTF8.GetBytes(e.StreamId));
        h.AppendData(BitConverter.GetBytes(e.StreamVersion));
        h.AppendData(Encoding.UTF8.GetBytes(e.EventType));
        h.AppendData(e.Data);                      // ciphertext if crypto-shredded: hash survives erasure
        h.AppendData(e.Metadata);
        return h.GetHashAndReset();
    }

    public static VerificationResult Verify(IEnumerable<StoredEventBytes> stream)
    {
        var prev = new byte[32];
        foreach (var e in stream)
        {
            var expected = Hash(prev, e);
            if (!CryptographicOperations.FixedTimeEquals(expected, e.ChainHash))
                return VerificationResult.Broken(e.StreamId, e.StreamVersion);
            prev = expected;
        }
        return VerificationResult.Ok(prev);        // last hash feeds the daily Merkle tree
    }
}
