public sealed class PostFailoverReconciler(IEventStore store, IProjectionRegistry projections, IPublishedLog published)
{
    public async Task RunAsync(CancellationToken ct)
    {
        var head = await store.HeadPositionAsync(ct);

        foreach (var p in projections.All)
            if (p.Checkpoint > head)
            {
                var touched = await p.StreamsAppliedAfterAsync(head, ct);     // per-row version tracking
                await p.RecomputeStreamsAsync(touched, ct);                    // fold from the surviving store
                await p.SetCheckpointAsync(head, ct);
            }

        await foreach (var msg in published.AfterAsync(head, ct))              // facts others saw, store lost
        {
            if (await store.ExistsAsync(msg.EventId, ct)) continue;
            await recovery.QueueAsync(new PhantomEvent(msg.EventId, msg.StreamId, msg.Payload), ct);   // re-append or compensate, human review for money
        }
    }
}
