public sealed class FeeRemediationJob(IEventStore store, IFeeCalculator correct, IApprovalService approvals, IReport report)
{
    public async Task RunAsync(string caseId, bool dryRun, CancellationToken ct)
    {
        await approvals.RequireAsync(caseId, ApprovalLevel.FinanceAndCompliance, ct);
        await foreach (var hit in store.QueryAsync(e => e.EventType == "FeeCharged" && e.Metadata.Build == "2026.09.14.3", ct))
        {
            var (events, version) = await store.ReadStreamAsync<ILedgerEvent>(hit.StreamId, ct);
            var state = events.Aggregate(LedgerState.Initial, LedgerDecider.Evolve);
            if (state.CorrectionsByCase.Contains((caseId, hit.EventId))) continue;            // resumable, idempotent

            var wrong = (FeeCharged)hit.Data;
            var right = correct.Recalculate(wrong.Inputs);
            var fixes = new List<ILedgerEvent> { new FeeReversed(wrong.AccountId, hit.EventId, wrong.Amount, caseId) };
            if (right.Amount > 0) fixes.Add(new FeeCharged(wrong.AccountId, right.Amount, wrong.Inputs, CorrectsEventId: hit.EventId, CaseId: caseId));

            report.Add(hit.StreamId, wrong.Amount, right.Amount);
            if (!dryRun) await store.AppendAsync(hit.StreamId, version, fixes, ct);
        }
        await report.PublishAsync(caseId, ct);                                                // Finance reviews the diff
    }
